files.examples/01_inlining.sql:
-- LEARN(sql.server-side.functions): a STABLE SQL table function is a parameterized view the planner sees through.
CREATE TABLE test_runs (
  id           int  PRIMARY KEY,
  test_case_id int  NOT NULL,
  status       text NOT NULL
);
INSERT INTO test_runs
SELECT g, g % 500, CASE WHEN g % 7 = 0 THEN 'failed' ELSE 'passed' END
FROM generate_series(1, 20000) AS g;
CREATE INDEX ON test_runs (test_case_id);
ANALYZE test_runs;

-- The same function three times: SQL + STABLE, SQL with the default
-- volatility (VOLATILE), and PL/pgSQL.
CREATE FUNCTION runs_of(case_id int) RETURNS SETOF test_runs
LANGUAGE sql STABLE
AS $$ SELECT * FROM test_runs WHERE test_case_id = case_id $$;

CREATE FUNCTION runs_of_volatile(case_id int) RETURNS SETOF test_runs
LANGUAGE sql
AS $$ SELECT * FROM test_runs WHERE test_case_id = case_id $$;

CREATE FUNCTION runs_of_plpgsql(case_id int) RETURNS SETOF test_runs
LANGUAGE plpgsql STABLE
AS $$ BEGIN RETURN QUERY SELECT * FROM test_runs WHERE test_case_id = case_id; END $$;

SELECT count(*) AS failed FROM runs_of(42) WHERE status = 'failed';

EXPLAIN (COSTS OFF) SELECT count(*) FROM runs_of(42) WHERE status = 'failed';
EXPLAIN (COSTS OFF) SELECT count(*) FROM runs_of_volatile(42) WHERE status = 'failed';
EXPLAIN (COSTS OFF) SELECT count(*) FROM runs_of_plpgsql(42) WHERE status = 'failed';

files.examples/02_body_checks.sql:
CREATE TABLE test_runs (test_case_id int NOT NULL, status text NOT NULL);
INSERT INTO test_runs VALUES (1, 'failed'), (1, 'passed'), (1, 'failed'), (2, 'passed');

-- 1. Body as a string: checked at CREATE, stored as text, parsed again when run.
CREATE FUNCTION failures_text(case_id int) RETURNS bigint
LANGUAGE sql STABLE
AS $$ SELECT count(*) FROM test_runs WHERE test_case_id = case_id AND status = 'failed' $$;

-- 2. SQL-standard body (PG 14): parsed now, stored as a parse tree,
--    with real dependencies on the table and its columns.
CREATE FUNCTION failures(case_id int) RETURNS bigint
LANGUAGE sql STABLE
RETURN (SELECT count(*) FROM test_runs WHERE test_case_id = case_id AND status = 'failed');

SELECT failures_text(1) AS text_body, failures(1) AS standard_body;

-- Rename a column both functions use.
ALTER TABLE test_runs RENAME COLUMN status TO outcome;
SELECT failures(1) AS standard_body_after_rename;
SELECT substring(pg_get_functiondef('failures'::regproc) FROM 'RETURN [^\n]*') AS stored_body;
SELECT failures_text(1);

files.examples/03_procedure.sql:
-- Runtime sql-nontx: autocommit, so CALL runs in a transaction of its own.
CREATE TABLE test_runs (id int PRIMARY KEY, ran_on date NOT NULL);
CREATE TABLE test_runs_archive (LIKE test_runs);
INSERT INTO test_runs
SELECT g, date '2026-01-01' + g / 100 FROM generate_series(1, 1000) AS g;

-- A procedure may COMMIT: each batch becomes durable on its own, so a
-- big cleanup never holds its locks for the whole run.
CREATE PROCEDURE archive_runs(cutoff date, batch_size int)
LANGUAGE plpgsql
AS $$
DECLARE
  moved int;
BEGIN
  LOOP
    WITH batch AS (
      DELETE FROM test_runs
      WHERE id IN (SELECT id FROM test_runs WHERE ran_on < cutoff ORDER BY id LIMIT batch_size)
      RETURNING *
    )
    INSERT INTO test_runs_archive SELECT * FROM batch;
    GET DIAGNOSTICS moved = ROW_COUNT;
    EXIT WHEN moved = 0;
    COMMIT;
    RAISE NOTICE 'archived % runs', moved;
  END LOOP;
END
$$;

CALL archive_runs('2026-01-04', 120);
SELECT (SELECT count(*) FROM test_runs) AS live,
       (SELECT count(*) FROM test_runs_archive) AS archived;

-- Inside a transaction block the caller owns the transaction, so the
-- procedure may not end it.
BEGIN;
CALL archive_runs('2026-01-08', 120);
